arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="Engineering insights, product updates, customer stories, and community perspectives from DeployCloud." />
  <style>
    :root {
      --bg: #fafafa;
      --surface: #ffffff;
      --ink: #171717;
      --muted: #666a73;
      --soft: #e8eaf0;
      --soft-2: #f3f4f7;
      --accent: #0072f5;
      --accent-dark: #0057c2;
      --orange: #ff7a1a;
      --navy: #071426;
      --shadow-sm: 0 8px 28px rgba(9, 20, 38, 0.06);
      --shadow-md: 0 18px 60px rgba(9, 20, 38, 0.11);
      --radius-lg: 28px;
      --radius-md: 20px;
      --radius-sm: 999px;
      --max: 1180px;
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      color: var(--ink);
      background:
        radial-gradient(circle at top left, rgba(0, 114, 245, 0.09), transparent 31rem),
        linear-gradient(180deg, #fff 0%, var(--bg) 43%, #fff 100%);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.55;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button, input { font: inherit; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      border-bottom: 1px solid rgba(232, 234, 240, 0.78);
      background: rgba(255, 255, 255, 0.84);
      backdrop-filter: blur(18px);
    }

    .nav {
      max-width: var(--max);
      margin: 0 auto;
      min-height: 72px;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 11px;
      font-weight: 750;
      letter-spacing: -0.03em;
      white-space: nowrap;
    }

    .brand-mark {
      width: 31px;
      height: 31px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(135deg, var(--ink), #28384d 58%, var(--accent));
      box-shadow: inset 0 1px 0 rgba(255,255,255,0.24), 0 10px 20px rgba(0,114,245,0.15);
    }

    .brand-mark svg { width: 17px; height: 17px; }

    .nav-links, .nav-actions {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .nav-link, .nav-action, .menu-trigger {
      border: 0;
      background: transparent;
      color: #30343b;
      padding: 9px 11px;
      border-radius: 11px;
      font-size: 14px;
      font-weight: 560;
      cursor: pointer;
      transition: background .18s ease, color .18s ease;
    }

    .nav-link:hover, .nav-action:hover, .menu-trigger:hover, .dropdown.open .menu-trigger {
      background: var(--soft-2);
      color: var(--ink);
    }

    .menu-trigger { display: inline-flex; align-items: center; gap: 5px; }
    .menu-trigger::after { content: "⌄"; font-size: 13px; transform: translateY(-1px); color: #7b808a; }

    .signup {
      background: var(--ink);
      color: #fff;
      border-radius: 999px;
      padding-inline: 15px;
      box-shadow: 0 10px 24px rgba(23,23,23,0.12);
    }

    .signup:hover { background: #000; color: #fff; }

    .dropdown { position: relative; }

    .mega-menu {
      position: absolute;
      top: calc(100% + 14px);
      left: 0;
      width: min(760px, calc(100vw - 48px));
      padding: 18px;
      border: 1px solid var(--soft);
      border-radius: 24px;
      background: rgba(255,255,255,0.98);
      box-shadow: var(--shadow-md);
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px) scale(.985);
      transform-origin: top left;
      transition: opacity .18s ease, transform .18s ease, visibility .18s ease;
    }

    .dropdown:hover .mega-menu, .dropdown.open .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateY(0) scale(1);
    }

    .mega-resources { width: min(540px, calc(100vw - 48px)); }

    .mega-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }

    .mega-section {
      padding: 14px;
      border-radius: 18px;
      background: linear-gradient(180deg, #fff, #fafbfe);
      border: 1px solid #eef0f4;
    }

    .mega-section h3 {
      margin: 0 0 10px;
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: .08em;
      color: #7b808a;
    }

    .mega-section a {
      display: block;
      padding: 9px 8px;
      border-radius: 11px;
      font-size: 14px;
      font-weight: 650;
    }

    .mega-section a:hover { background: #f0f6ff; color: var(--accent); }
    .mega-section span { display: block; margin-top: 2px; font-size: 12px; font-weight: 450; color: var(--muted); }

    .mobile-menu-button { display: none; }

    main { overflow: hidden; }

    .container { max-width: var(--max); margin: 0 auto; padding: 0 24px; }

    .hero {
      padding: 82px 0 34px;
      display: grid;
      grid-template-columns: minmax(0, 1.1fr) 380px;
      gap: 54px;
      align-items: end;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 18px;
      color: var(--accent);
      font-size: 13px;
      font-weight: 720;
      letter-spacing: .04em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: var(--accent);
      box-shadow: 0 0 0 6px rgba(0,114,245,.1);
    }

    h1 {
      margin: 0;
      max-width: 820px;
      font-size: clamp(48px, 8vw, 88px);
      line-height: .93;
      letter-spacing: -0.075em;
    }

    .hero-copy {
      margin: 26px 0 0;
      max-width: 690px;
      color: #4b515d;
      font-size: 19px;
      line-height: 1.7;
    }

    .hero-panel {
      position: relative;
      padding: 24px;
      border: 1px solid var(--soft);
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,0.78);
      box-shadow: var(--shadow-sm);
    }

    .hero-panel::before {
      content: "";
      position: absolute;
      inset: -1px;
      z-index: -1;
      border-radius: inherit;
      background: linear-gradient(135deg, rgba(0,114,245,.28), transparent 40%, rgba(255,122,26,.18));
    }

    .hero-panel strong { display: block; font-size: 34px; letter-spacing: -.055em; line-height: 1; }
    .hero-panel p { margin: 10px 0 0; color: var(--muted); font-size: 14px; }

    .mini-stats {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
      margin-top: 20px;
    }

    .mini-stat {
      padding: 14px;
      border-radius: 18px;
      background: #f7f9fc;
      border: 1px solid #edf0f5;
    }

    .mini-stat b { display: block; font-size: 20px; letter-spacing: -.04em; }
    .mini-stat span { display: block; margin-top: 2px; color: var(--muted); font-size: 12px; }

    .filter-shell {
      margin: 30px auto 42px;
      padding: 16px;
      border: 1px solid var(--soft);
      border-radius: 26px;
      background: rgba(255,255,255,.86);
      box-shadow: var(--shadow-sm);
      display: flex;
      gap: 14px;
      align-items: center;
      justify-content: space-between;
    }

    .filters {
      display: flex;
      gap: 9px;
      overflow-x: auto;
      scrollbar-width: none;
      padding-bottom: 1px;
    }

    .filters::-webkit-scrollbar { display: none; }

    .filter-btn {
      flex: 0 0 auto;
      border: 1px solid #e4e7ee;
      background: #fff;
      color: #3f4651;
      border-radius: var(--radius-sm);
      padding: 9px 14px;
      font-size: 14px;
      font-weight: 690;
      cursor: pointer;
      transition: transform .15s ease, background .15s ease, color .15s ease, border-color .15s ease, box-shadow .15s ease;
    }

    .filter-btn:hover { transform: translateY(-1px); border-color: #cdd7e8; box-shadow: 0 7px 16px rgba(9,20,38,.06); }
    .filter-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; box-shadow: 0 10px 24px rgba(0,114,245,.22); }

    .search-wrap {
      position: relative;
      flex: 0 0 275px;
    }

    .search-wrap svg {
      position: absolute;
      left: 13px;
      top: 50%;
      transform: translateY(-50%);
      width: 17px;
      height: 17px;
      color: #7a818c;
    }

    #searchInput {
      width: 100%;
      border: 1px solid #e4e7ee;
      border-radius: var(--radius-sm);
      padding: 10px 14px 10px 40px;
      color: var(--ink);
      background: #fff;
      outline: none;
      transition: border-color .15s ease, box-shadow .15s ease;
    }

    #searchInput:focus { border-color: rgba(0,114,245,.65); box-shadow: 0 0 0 4px rgba(0,114,245,.1); }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 22px;
    }

    .section-heading h2 {
      margin: 0;
      font-size: clamp(30px, 4vw, 46px);
      line-height: 1;
      letter-spacing: -.055em;
    }

    .section-heading p { margin: 0; max-width: 500px; color: var(--muted); }

    .featured-grid {
      display: grid;
      grid-template-columns: 1.18fr .82fr;
      grid-template-rows: repeat(2, minmax(230px, auto));
      gap: 18px;
      margin-bottom: 72px;
    }

    .feature-card {
      position: relative;
      min-height: 100%;
      overflow: hidden;
      border: 1px solid #e5e8ef;
      border-radius: var(--radius-lg);
      background: #fff;
      box-shadow: var(--shadow-sm);
      padding: 26px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
    }

    .feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); border-color: #d3d9e4; }

    .feature-card.primary {
      grid-row: 1 / 3;
      min-height: 500px;
      color: #fff;
      background:
        radial-gradient(circle at 88% 12%, rgba(0,114,245,.74), transparent 28%),
        radial-gradient(circle at 16% 88%, rgba(255,122,26,.36), transparent 28%),
        linear-gradient(145deg, #071426, #101b2e 62%, #15243b);
      border-color: rgba(255,255,255,.12);
    }

    .feature-card.primary::before {
      content: "";
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(255,255,255,.08) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.08) 1px, transparent 1px);
      background-size: 54px 54px;
      mask-image: linear-gradient(180deg, rgba(0,0,0,.65), transparent 82%);
    }

    .feature-card > * { position: relative; z-index: 1; }

    .meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: #727885; font-size: 13px; font-weight: 650; }
    .primary .meta, .primary .excerpt { color: rgba(255,255,255,.72); }

    .category {
      display: inline-flex;
      align-items: center;
      width: fit-content;
      border-radius: 999px;
      padding: 5px 9px;
      background: #eef6ff;
      color: var(--accent);
      font-size: 12px;
      font-weight: 760;
    }

    .primary .category { background: rgba(255,255,255,.14); color: #fff; border: 1px solid rgba(255,255,255,.18); }

    .feature-card h3 {
      margin: 18px 0 12px;
      font-size: clamp(24px, 3vw, 38px);
      line-height: 1.02;
      letter-spacing: -.055em;
    }

    .feature-card:not(.primary) h3 { font-size: 25px; }

    .excerpt { margin: 0; color: #5d6571; font-size: 15px; line-height: 1.65; }
    .primary .excerpt { font-size: 17px; max-width: 620px; }

    .author-row { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 26px; }
    .author { display: flex; align-items: center; gap: 10px; color: #525966; font-size: 14px; font-weight: 650; }
    .primary .author { color: rgba(255,255,255,.84); }

    .avatar {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(135deg, var(--accent), #7c3aed);
      font-size: 12px;
      font-weight: 800;
      box-shadow: inset 0 1px 0 rgba(255,255,255,.24);
    }

    .read-link { color: var(--accent); font-weight: 750; font-size: 14px; }
    .primary .read-link { color: #fff; }

    .feature-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-top: 28px;
    }

    .feature-stat {
      border: 1px solid rgba(255,255,255,.15);
      border-radius: 18px;
      background: rgba(255,255,255,.08);
      padding: 14px;
    }

    .feature-stat b { display: block; font-size: 25px; line-height: 1; letter-spacing: -.045em; }
    .feature-stat span { display: block; margin-top: 7px; font-size: 12px; color: rgba(255,255,255,.68); line-height: 1.35; }

    .latest-toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 20px;
    }

    .result-count { color: var(--muted); font-size: 14px; }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 18px;
    }

    .post-card {
      min-height: 264px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      border: 1px solid #e6e9ef;
      border-radius: 24px;
      background: #fff;
      padding: 22px;
      box-shadow: 0 1px 0 rgba(9,20,38,.03);
      transition: transform .17s ease, box-shadow .17s ease, border-color .17s ease;
      animation: cardIn .24s ease both;
    }

    .post-card:hover { transform: translateY(-4px); border-color: #d2d9e5; box-shadow: var(--shadow-sm); }

    @keyframes cardIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

    .post-card h3 { margin: 14px 0 9px; font-size: 22px; line-height: 1.14; letter-spacing: -.04em; }
    .post-card .excerpt { font-size: 14px; }

    .post-footer { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 22px; }

    .no-results {
      display: none;
      border: 1px dashed #cbd5e1;
      border-radius: 26px;
      background: #fff;
      padding: 52px 24px;
      text-align: center;
      color: var(--muted);
    }

    .no-results strong { display: block; margin-bottom: 8px; color: var(--ink); font-size: 22px; letter-spacing: -.03em; }

    .show-more-wrap { display: flex; justify-content: center; margin: 32px 0 82px; }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      border: 1px solid #dfe4ec;
      border-radius: 999px;
      background: #fff;
      color: var(--ink);
      padding: 12px 18px;
      font-weight: 760;
      cursor: pointer;
      transition: transform .16s ease, box-shadow .16s ease, background .16s ease, border-color .16s ease;
    }

    .btn:hover { transform: translateY(-1px); box-shadow: 0 12px 26px rgba(9,20,38,.08); border-color: #cbd4e2; }
    .btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; box-shadow: 0 14px 30px rgba(0,114,245,.22); }
    .btn.primary:hover { background: var(--accent-dark); }

    .cta {
      margin-bottom: 82px;
      border-radius: 34px;
      background:
        radial-gradient(circle at 8% 0%, rgba(0,114,245,.45), transparent 28%),
        radial-gradient(circle at 90% 110%, rgba(255,122,26,.32), transparent 32%),
        var(--navy);
      color: #fff;
      padding: 42px;
      display: grid;
      grid-template-columns: minmax(0, 1fr) 340px;
      gap: 32px;
      box-shadow: var(--shadow-md);
    }

    .cta h2 { margin: 0; font-size: clamp(32px, 5vw, 56px); line-height: 1; letter-spacing: -.065em; max-width: 760px; }
    .cta p { margin: 18px 0 0; color: rgba(255,255,255,.7); max-width: 650px; }
    .cta-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
    .cta .btn:not(.primary) { background: rgba(255,255,255,.1); color: #fff; border-color: rgba(255,255,255,.2); }

    .enterprise-card {
      align-self: stretch;
      padding: 24px;
      border-radius: 24px;
      background: rgba(255,255,255,.08);
      border: 1px solid rgba(255,255,255,.14);
    }

    .enterprise-card h3 { margin: 0 0 10px; font-size: 22px; letter-spacing: -.04em; }
    .enterprise-card p { margin: 0 0 22px; font-size: 14px; }

    .site-footer {
      border-top: 1px solid var(--soft);
      background: #fff;
      padding: 54px 0 34px;
    }

    .footer-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 38px; }
    .status { display: inline-flex; align-items: center; gap: 9px; color: #166534; background: #ecfdf3; border: 1px solid #bbf7d0; border-radius: 999px; padding: 8px 12px; font-size: 13px; font-weight: 750; }
    .status::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #22c55e; }

    .footer-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 26px 20px; }
    .footer-col h3 { margin: 0 0 12px; color: #737984; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; }
    .footer-col a { display: block; margin: 8px 0; color: #414852; font-size: 14px; }
    .footer-col a:hover { color: var(--accent); }

    .footer-bottom { margin-top: 38px; padding-top: 22px; border-top: 1px solid var(--soft); color: var(--muted); font-size: 13px; }

    @media (max-width: 980px) {
      .nav { flex-wrap: wrap; padding-block: 14px; }
      .nav-links, .nav-actions { width: 100%; justify-content: center; flex-wrap: wrap; }
      .mega-menu { left: 50%; transform: translate(-50%, -8px) scale(.985); }
      .dropdown:hover .mega-menu, .dropdown.open .mega-menu { transform: translate(-50%, 0) scale(1); }
      .hero { grid-template-columns: 1fr; padding-top: 56px; gap: 28px; }
      .filter-shell { flex-direction: column; align-items: stretch; }
      .search-wrap { flex-basis: auto; }
      .featured-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
      .feature-card.primary { grid-row: auto; min-height: 0; }
      .posts-grid { grid-template-columns: repeat(2, 1fr); }
      .cta { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 680px) {
      .container, .nav { padding-left: 16px; padding-right: 16px; }
      .nav-links { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 2px; }
      .nav-actions { justify-content: flex-start; }
      .mega-menu { position: fixed; left: 16px; right: 16px; top: 118px; width: auto; transform: translateY(-8px) scale(.985); max-height: calc(100vh - 140px); overflow: auto; }
      .dropdown:hover .mega-menu, .dropdown.open .mega-menu { transform: translateY(0) scale(1); }
      .mega-grid { grid-template-columns: 1fr; }
      h1 { font-size: 50px; }
      .hero-copy { font-size: 17px; }
      .section-heading, .latest-toolbar, .footer-top { align-items: flex-start; flex-direction: column; }
      .feature-stats, .mini-stats, .posts-grid { grid-template-columns: 1fr; }
      .feature-card, .post-card, .cta { border-radius: 22px; padding: 22px; }
      .cta { margin-bottom: 56px; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 430px) {
      .nav-action.ai, .nav-action.login { display: none; }
      .footer-grid { grid-template-columns: 1fr; }
      .hero-panel { padding: 18px; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <nav class="nav" aria-label="Primary navigation">
      <a class="brand" href="index.html" aria-label="DeployCloud Blog home">
        <span class="brand-mark" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none"><path d="M12 3 4.8 16.4c-.5.9.2 2 1.2 2h12c1 0 1.7-1.1 1.2-2L12 3Z" fill="currentColor"/><path d="M12 8.2 8.6 16h6.8L12 8.2Z" fill="#0072F5"/></svg>
        </span>
        DeployCloud Blog
      </a>

      <div class="nav-links">
        <div class="dropdown" data-dropdown>
          <button class="menu-trigger" type="button" aria-expanded="false">Products</button>
          <div class="mega-menu" role="menu">
            <div class="mega-grid">
              <section class="mega-section">
                <h3>AI Cloud</h3>
                <a href="#">AI Gateway<span>One endpoint, all your models</span></a>
                <a href="#">Sandbox<span>Isolated, safe code execution</span></a>
                <a href="#">DeployCloud Agent<span>An agent that knows your stack</span></a>
                <a href="#">AI SDK<span>The AI Toolkit for TypeScript</span></a>
                <a href="#">v0<span>Build applications with AI</span></a>
              </section>
              <section class="mega-section">
                <h3>Core Platform</h3>
                <a href="#">CI/CD<span>Helping teams ship 6× faster</span></a>
                <a href="#">Content Delivery<span>Fast, scalable, and reliable</span></a>
                <a href="#">Fluid Compute<span>Servers, in serverless form</span></a>
                <a href="#">Workflows<span>Long-running workflows at scale</span></a>
                <a href="#">Observability<span>Trace every step</span></a>
              </section>
              <section class="mega-section">
                <h3>Security</h3>
                <a href="#">Bot Management</a>
                <a href="#">BotID</a>
                <a href="#">Platform Security</a>
                <a href="#">Web Application Firewall</a>
              </section>
            </div>
          </div>
        </div>
        <div class="dropdown" data-dropdown>
          <button class="menu-trigger" type="button" aria-expanded="false">Resources</button>
          <div class="mega-menu mega-resources" role="menu">
