      { title: "DeployCloud named a leader in developer platforms", category: "Press", date: "Mar 10", author: "DeployCloud Newsroom", excerpt: "Industry analysts recognized DeployCloud for developer experience, enterprise controls, and momentum in AI-native infrastructure." },
      { title: "BotID now supports adaptive challenge policies", category: "Security", date: "Mar 5", author: "Security Team", excerpt: "Security teams can tune bot mitigation by risk profile while preserving fast paths for verified users and trusted workloads." },
      { title: "How retailers scale launch moments on DeployCloud", category: "Customers", date: "Feb 27", author: "Customer Engineering", excerpt: "A look at composable commerce teams preparing for traffic spikes with CDN controls, observability, and workflow automation." },
      { title: "Inside DeployCloud Academy's new AI curriculum", category: "Community", date: "Feb 20", author: "Academy Team", excerpt: "New lessons help developers understand model routing, sandboxed execution, durable workflows, and responsible agent review." }
    ];

    const footerLinks = {
      "Get Started": ["Templates", "Supported Frameworks", "Marketplace", "Domains"],
      "Build": ["Next.js on DeployCloud", "Turborepo", "v0"],
      "Scale": ["Content Delivery Network", "Fluid Compute", "CI/CD", "Observability", "AI Gateway", "DeployCloud Agent"],
      "Secure": ["Platform Security", "Web Application Firewall", "Bot Management", "BotID", "Sandbox"],
      "Resources": ["Pricing", "Customers", "Enterprise", "Articles", "Startups", "Solution Partners"],
      "Learn": ["Docs", "Blog", "Changelog", "Knowledge Base", "Academy", "Community"],
      "Frameworks": ["Next.js", "Nuxt", "Svelte", "Nitro", "Turbo"],
      "SDKs": ["AI SDK", "Workflow SDK", "Flags SDK", "Chat SDK", "Streamdown AI"],
      "Use Cases": ["Composable Commerce", "Multi-tenant Platforms", "Web Apps", "Marketing Sites", "Platform Engineers", "Design Engineers"],
      "Company": ["About", "Careers", "Help", "Press", "Legal", "Privacy Policy"],
      "Community": ["Open Source Program", "Events", "GitHub", "LinkedIn", "X", "YouTube"]
    };

    const state = { category: "All Posts", visible: 6, query: "" };
    const filtersEl = document.getElementById("filters");
    const gridEl = document.getElementById("postsGrid");
    const searchInput = document.getElementById("searchInput");
    const noResultsEl = document.getElementById("noResults");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const resultCountEl = document.getElementById("resultCount");

    function initials(name) {
      return name.split(/\s|and|,/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
    }

    function getFilteredPosts() {
      const query = state.query.trim().toLowerCase();
      return posts.filter(post => {
        const matchesCategory = state.category === "All Posts" || post.category === state.category;
        const searchable = `${post.title} ${post.category} ${post.date} ${post.author} ${post.excerpt}`.toLowerCase();
        return matchesCategory && (!query || searchable.includes(query));
      });
    }

    function renderFilters() {
      filtersEl.innerHTML = categories.map(category => `
        <button class="filter-btn${category === state.category ? " active" : ""}" type="button" data-category="${category}" aria-pressed="${category === state.category}">${category}</button>
      `).join("");
    }

    function renderPosts() {
      const filtered = getFilteredPosts();
      const visiblePosts = filtered.slice(0, state.visible);
      gridEl.innerHTML = visiblePosts.map(post => `
        <article class="post-card">
          <div>
            <span class="category">${post.category}</span>
            <div class="meta" style="margin-top:12px"><span>${post.date}</span><span>·</span><span>${post.author}</span></div>
            <h3>${post.title}</h3>
            <p class="excerpt">${post.excerpt}</p>
          </div>
          <div class="post-footer">
            <div class="author"><span class="avatar">${initials(post.author)}</span><span>${post.author}</span></div>
            <a class="read-link" href="#" aria-label="Read ${post.title}">Read →</a>
          </div>
        </article>
      `).join("");

      noResultsEl.style.display = filtered.length ? "none" : "block";
      gridEl.style.display = filtered.length ? "grid" : "none";
      showMoreBtn.style.display = filtered.length > state.visible ? "inline-flex" : "none";
      resultCountEl.textContent = filtered.length === 1 ? "1 post found" : `${filtered.length} posts found`;
    }

    filtersEl.addEventListener("click", event => {
      const button = event.target.closest("button[data-category]");
      if (!button) return;
      state.category = button.dataset.category;
      state.visible = 6;
      renderFilters();
      renderPosts();
    });

    searchInput.addEventListener("input", event => {
      state.query = event.target.value;
      state.visible = 6;
      renderPosts();
    });

    showMoreBtn.addEventListener("click", () => {
      state.visible += 6;
      renderPosts();
    });

    document.querySelectorAll("[data-dropdown]").forEach(dropdown => {
      const trigger = dropdown.querySelector("button");
      trigger.addEventListener("click", event => {
        event.stopPropagation();
        const isOpen = dropdown.classList.toggle("open");
        trigger.setAttribute("aria-expanded", isOpen ? "true" : "false");
        document.querySelectorAll("[data-dropdown]").forEach(other => {
          if (other !== dropdown) {
            other.classList.remove("open");
            other.querySelector("button").setAttribute("aria-expanded", "false");
          }
        });
      });
    });

    document.addEventListener("click", () => {
      document.querySelectorAll("[data-dropdown]").forEach(dropdown => {
        dropdown.classList.remove("open");
        dropdown.querySelector("button").setAttribute("aria-expanded", "false");
      });
    });

    document.getElementById("footerGrid").innerHTML = Object.entries(footerLinks).map(([heading, links]) => `
      <section class="footer-col">
        <h3>${heading}</h3>
        ${links.map(link => `<a href="#">${link}</a>`).join("")}
      </section>
    `).join("");

    renderFilters();
    renderPosts();
  </script>
</body>
</html>
